abstract class Employee{String name;Employee(String n){name=n;}abstract double getSalary();}class FullTimeEmployee extends Employee{FullTimeEmployee(String n){super(n);}double getSalary(){return 50000;}}class PartTimeEmployee extends Employee{PartTimeEmployee(String n){super(n);}double getSalary(){return 20000;}}
class LeaveRequest{private Employee employee;private String status="Pending";LeaveRequest(Employee e){employee=e;}String getStatus(){return status;}void review(boolean approved){if(!status.equals("Pending")){System.out.println("Request already reviewed");return;}status=approved?"Approved":"Rejected";System.out.println(employee.name+": "+status);}void changeStatus(String n){if(!status.equals("Pending")){System.out.println("Cannot change status from "+status+" to "+n);return;}if(n.equals("Approved")||n.equals("Rejected"))status=n;}}
public class EmployeeLeaveWorkflow{public static void main(String[] args){Employee j=new FullTimeEmployee("John"),n=new PartTimeEmployee("Jane");LeaveRequest a=new LeaveRequest(j);System.out.println("John: "+a.getStatus());a.review(true);LeaveRequest b=new LeaveRequest(n);System.out.println("Jane: "+b.getStatus());b.review(false);a.changeStatus("Pending");}}